{
  "name": "opencode-web-deepsearch",
  "version": "1.0.13",
  "description": "DuckDuckGo web search tool for OpenCode with deep search capabilities",
  "main": "dist/index.js",
  "types": "dist/index.d.ts",
  "type": "module",
  "scripts": {
    "build": "tsc",
    "test": "vitest run",
    "test:watch": "vitest",
    "prepublishOnly": "tsc"
  },
  "keywords": [
    "opencode",
    "websearch",
    "duckduckgo",
    "ai",
    "mcp"
  ],
  "repository": {
    "type": "git",
    "url": "https://github.com/noxgle/opencode-web-deepsearch"
  },
  "homepage": "https://github.com/noxgle/opencode-web-deepsearch#readme",
  "author": "",
  "license": "MIT",
  "files": [
    "dist/",
    "scripts/WebSearchAgent.py",
    "README.md"
  ],
  "dependencies": {
    "@opencode-ai/plugin": "^1.0.0"
  },
  "devDependencies": {
    "@types/bun": "^1.3.11",
    "@types/node": "^20.0.0",
    "typescript": "^5.0.0",
    "vitest": "^4.1.4"
  },
  "engines": {
    "node": ">=18.0.0",
    "python": ">=3.8"
  },
  "opencode": {
    "tools": [
      "web-deepsearch"
    ]
  }
}
